// === Universal normalizer ===
const raw = $input.first().json || {};

// CASO 0: Tool call de ElevenLabs durante la llamada
const isToolCall = (raw.body?.event === 'account_requested' || raw.body?.intent === 'OPEN_FREE_ACCOUNT' ||
                    raw.event === 'account_requested' || raw.intent === 'OPEN_FREE_ACCOUNT');
if (isToolCall) {
  const b = raw.body || raw;
  const cleanPhone = String(b.phone || '').replace(/[^0-9]/g, '');
  const waNumber = String(b.whatsapp_number || b.phone || '').replace(/[^0-9]/g, '') || cleanPhone;
  console.log('🟡 Tool call ElevenLabs | phone:', cleanPhone, '| whatsapp:', waNumber, '| name:', b.full_name);
  return [{ json: {
    source: 'elevenlabs_tool',
    lead_id: String(b.lead_id || `CALL-${cleanPhone}`).trim(),
    full_name: String(b.full_name || '').trim(),
    phone: cleanPhone,
    whatsapp_number: waNumber,
    email: cleanPhone + '@leads.landmarkmarkets.io',
    country: String(b.country || 'India').trim(),
    elevenlabs_call_id: b.conversation_id || '',
    status_raw: '',
    duration_secs: 0,
    transcript: '',
    sentiment: '',
    intent: '',
    classification: 'INTERESTED',
    callback_requested: false,
    callback_date: '',
    interested: true,
    account_opened: 'PENDING',
    conversation_summary: 'Account requested during call'
  }}];
}

// CASO 1: Sub-workflow desde WhatsApp bot
const isSubworkflow = !!(raw.phone && raw.full_name && !raw.body && !raw.data && !raw.transcript);
if (isSubworkflow) {
  console.log('🟦 Sub-workflow path (WhatsApp bot)', JSON.stringify(raw));
  const cleanPhone = String(raw.phone || '').replace(/[^0-9]/g, '');
  return [{ json: {
    source: 'subworkflow',
    lead_id: String(raw.lead_id || `WA-${cleanPhone}`).trim(),
    full_name: String(raw.full_name || '').trim(),
    phone: cleanPhone,
    country: String(raw.country || 'India').trim(),
    elevenlabs_call_id: '',
    status_raw: '',
    duration_secs: 0,
    transcript: '',
    sentiment: '',
    intent: '',
    classification: 'INTERESTED',
    callback_requested: false,
    callback_date: '',
    interested: true,
    account_opened: 'PENDING',
    conversation_summary: 'Account creation from WhatsApp bot'
  }}];
}

// CASO 2: ElevenLabs post-call webhook (código original sin cambios)
console.log('🟪 ElevenLabs webhook path');
const body = raw.body || raw;
const data = body.data || body;
const lead = (data.conversation_initiation_client_data && data.conversation_initiation_client_data.dynamic_variables) || data.dynamic_variables || {};
const transcriptArr = data.transcript || data.transcripts || [];
const transcriptText = Array.isArray(transcriptArr)
  ? transcriptArr.map(t => `${t.role || t.speaker || 'agent'}: ${t.message || t.text || ''}`).join('\n')
  : (typeof transcriptArr === 'string' ? transcriptArr : '');
const analysis = data.analysis || {};
const duration = data.metadata?.call_duration_secs || data.call_duration_secs || data.duration || 0;
const statusRaw = data.status || data.call_status || analysis.call_successful || '';
const callId = data.conversation_id || data.call_sid || data.conversationId || '';
let classification = 'NO_ANSWER';
if (statusRaw && /failed|no.?answer|busy|noanswer|no_answer/i.test(statusRaw)) {
  classification = 'NO_ANSWER';
} else if (/wrong number|galat number|गलत नंबर/i.test(transcriptText)) {
  classification = 'WRONG_NUMBER';
} else if (/do not call|dnc|mat karo|call mat/i.test(transcriptText)) {
  classification = 'DO_NOT_CALL';
} else if (/callback|baad mein|बाद में|kal call/i.test(transcriptText)) {
  classification = 'CALLBACK_REQUESTED';
} else if (/not interested|nahin chahiye|interest nahi/i.test(transcriptText)) {
  classification = 'NOT_INTERESTED';
} else if (/yes|haan|हाँ|interested|account khol|deposit|ready/i.test(transcriptText)) {
  classification = 'INTERESTED';
} else if (analysis.intent === 'interested' || analysis.outcome === 'interested') {
  classification = 'INTERESTED';
}
let fullName = lead.full_name || '';
const m = transcriptText.match(/(?:naam|name|नाम)[^a-zA-Z\u0900-\u097F]{0,8}([a-zA-Z\u0900-\u097F][a-zA-Z\u0900-\u097F .]{1,60})/i);
if (m && m[1] && !fullName) fullName = m[1].trim();
const callbackDate = classification === 'CALLBACK_REQUESTED'
  ? new Date(Date.now() + 24*60*60*1000).toISOString()
  : '';
const cleanPhone = String(lead.phone || data.to_number || '').replace(/[^0-9]/g, '');
return [{ json: {
  source: 'webhook',
  lead_id: String(lead.lead_id || data.lead_id || `EL-${callId}`).trim(),
  full_name: fullName,
  phone: cleanPhone,
  country: lead.country || 'India',
  elevenlabs_call_id: callId,
  status_raw: statusRaw,
  duration_secs: duration,
  transcript: transcriptText,
  sentiment: analysis.sentiment || '',
  intent: analysis.intent || analysis.user_intent || '',
  classification,
  callback_requested: classification === 'CALLBACK_REQUESTED',
  callback_date: callbackDate,
  interested: classification === 'INTERESTED',
  account_opened: classification === 'INTERESTED' ? 'PENDING' : '',
  conversation_summary: (analysis.transcript_summary || analysis.summary || transcriptText.slice(0, 800))
}}];

// Evalúa el resultado del Lookup. Maneja 0 filas, fila vacía y match por phone.
const preflight = $('🛂 Pre-flight Check1').first().json;
const wantedPhone = String(preflight.phone || '').replace(/[^0-9]/g, '');
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);

let match = null;
for (const r of rows) {
  const rowPhone = String(r.phone || '').replace(/[^0-9]/g, '');
  const rowWa    = String(r.whatsapp_phone || '').replace(/[^0-9]/g, '');
  const hasUser  = String(r.atlantis_username || '').trim().length > 0;
  const opened   = String(r.account_opened || '').toLowerCase() === 'true';
  if ((rowPhone === wantedPhone || rowWa === wantedPhone) && hasUser && opened) {
    match = r;
    break;
  }
}

if (match) {
  console.log('♻️ Existing account found | phone:', wantedPhone, '| user:', match.atlantis_username);
  return [{ json: {
    exists: true,
    username: match.atlantis_username,
    password: match.atlantis_password,
    full_name: match.full_name || preflight.full_name,
    lead_id: match.lead_id || preflight.lead_id,
    phone: wantedPhone,
    whatsapp_number: preflight.whatsapp_number || wantedPhone,
    country: preflight.country || 'India'
  }}];
}

console.log('🆕 No existing account | phone:', wantedPhone, '— proceeding to create');
return [{ json: {
  exists: false,
  lead_id: preflight.lead_id,
  full_name: preflight.full_name,
  phone: wantedPhone,
  whatsapp_number: preflight.whatsapp_number || wantedPhone,
  country: preflight.country || 'India',
  email: preflight.email || ''
}}];

const sheet = $input.first().json;
console.log('♻️ Existing account → resending credentials | user:', sheet.username);
return [{ json: {
  success: true,
  duplicate: true,
  is_existing: true,
  username: sheet.username,
  password: sheet.password,
  account_id: sheet.lead_id || '',
  full_name: sheet.full_name,
  lead_id: sheet.lead_id,
  phone: sheet.phone,
  whatsapp_number: sheet.whatsapp_number || sheet.phone,
  country: sheet.country || 'India'
}}];

const d = $input.first().json;
console.log('🆕 New account credentials ready | user:', d.username);
return [{ json: {
  success: true,
  duplicate: false,
  is_existing: false,
  username: d.username,
  password: d.password,
  account_id: d.account_id || '',
  full_name: d.full_name,
  lead_id: d.lead_id,
  phone: d.phone,
  whatsapp_number: d.whatsapp_number || d.phone,
  country: d.country || 'India',
  http_status: d.http_status
}}];

const d = $input.first().json;
const missing = [];
if (!d.full_name || d.full_name.length < 2) missing.push('full_name');
if (!d.phone || d.phone.length < 6) missing.push('phone');
if (missing.length > 0) {
  console.error('❌ Missing required fields:', missing.join(', '));
  throw new Error('Missing required fields for Atlantis: ' + missing.join(', '));
}
const cleanPhone = String(d.phone || '').replace(/[^0-9]/g, '');
const waPhone = String(d.whatsapp_number || d.phone || '').replace(/[^0-9]/g, '') || cleanPhone;
console.log('✅ Pre-flight OK — Phone:', cleanPhone, '| WA:', waPhone, '| Name:', d.full_name);
return [{ json: {
  lead_id: String(d.lead_id || `WA-${cleanPhone}`).trim(),
  full_name: String(d.full_name || '').trim(),
  phone: cleanPhone,
  whatsapp_number: waPhone,
  country: String(d.country || 'India').trim(),
  email: String(d.email || '').trim()
}}];

// Lead fields now arrive directly on the input (❓ Account Already Exists? → here),
// since 🔐 Atlantis Login1 no longer exists.
// If they don't (e.g. this node is ever re-wired upstream again), restore the old reference:
// $('🆕 Check Existing Account').first().json
const lead = $input.first().json;

console.log('🧱 Building lead-account payload | lead_id:', lead.lead_id, '| phone:', lead.phone);

return [{
  json: {
    lead_id: String(lead.lead_id ?? ''),
    full_name: String(lead.full_name ?? ''),
    phone: String(lead.phone ?? ''),
    whatsapp_number: String(lead.whatsapp_number ?? lead.phone ?? ''),
    country: String(lead.country || 'India'),
    payload: {
      lead_id: String(lead.lead_id ?? ''),
      full_name: String(lead.full_name ?? ''),
      phone: String(lead.phone ?? ''),
      whatsapp_number: String(lead.whatsapp_number ?? lead.phone ?? ''),
      country: String(lead.country || 'India'),
      market: 'IND', // <- the one place that decides which brand these leads land in
    },
  },
}];

const resp = $input.first().json || {};
const status = resp.statusCode || resp.status || 0;
const body = resp.body || resp;
const ctx = $('🧱 Build Atlantis Payload1').first().json;

console.log('👤 Lead-account create — HTTP:', status);
console.log('👤 Response preview:', JSON.stringify(body).slice(0, 600));

const apiSuccess = body?.success;
const apiErrorCode = body?.errorCode || '';
const apiMessage = body?.message || '';

// Narrowed duplicate detection — the API returns a stable error code, no more string-matching.
const isDuplicate = apiErrorCode === 'ACCOUNT_ALREADY_EXISTS';

if (status >= 400 || apiSuccess === false) {
  const errorMsg = apiMessage ||
                   body?.error?.message ||
                   body?.errors?.[0]?.message ||
                   body?.errors?.[0] ||
                   (Array.isArray(body?.errors) ? body.errors.join('; ') : null) ||
                   JSON.stringify(body).slice(0, 300);
  console.error('🔴 Lead-account create FAILED. HTTP', status, 'errorCode:', apiErrorCode, '—', errorMsg);
  return [{ json: {
    success: false,
    duplicate: isDuplicate,
    http_status: status,
    atlantis_error_code: apiErrorCode,
    error_message: errorMsg,
    username: '',
    password: '',
    phone: ctx.phone,
    whatsapp_number: ctx.whatsapp_number || ctx.phone,
    full_name: ctx.full_name,
    lead_id: ctx.lead_id,
    country: ctx.country,
    raw_response: body
  }}];
}

// Username/password are now minted by the API — read them from the response, not from ctx.
const created = body?.data || {};
const username = created.username || '';
const password = created.password || '';
const accountId = created.accountID || created.accountId || created.id || '';
const userId = created.userId || created.id || '';

console.log('✅ Lead-account created. accountId (portal trader id, not ARK account):', accountId, 'userId:', userId);

return [{ json: {
  success: true,
  duplicate: false,
  http_status: status,
  account_id: accountId,
  user_id: userId,
  username,
  password,
  phone: ctx.phone,
  whatsapp_number: ctx.whatsapp_number || ctx.phone,
  full_name: ctx.full_name,
  lead_id: ctx.lead_id,
  country: ctx.country,
  raw_response: body
}}];

const d = $input.first().json;
let waStatus = 0;
try { waStatus = $('📲 Send WhatsApp Credentials1').first().json?.statusCode || 0; } catch(e) {}
console.log('🎉 SUCCESS — user:', d.username, '| existing:', d.is_existing, '| account_id:', d.account_id);
return [{ json: {
  status: 'SUCCESS',
  is_existing: d.is_existing || false,
  username: d.username,
  password: d.password,
  account_id: d.account_id,
  phone: d.phone,
  full_name: d.full_name,
  lead_id: d.lead_id,
  whatsapp_status: waStatus
}}];

const d = $input.first().json;
console.error('🔴 FAILURE — lead_id:', d.lead_id, '| http:', d.http_status, '| error:', d.error_message);
return [{ json: {
  status: 'FAILURE',
  error_message: d.error_message || 'unknown',
  http_status: d.http_status,
  atlantis_error_code: d.atlantis_error_code || '',
  phone: d.phone,
  full_name: d.full_name,
  lead_id: d.lead_id,
  duplicate: d.duplicate || false
}}];

// Buscamos el contexto del cliente (viene de la rama que se haya ejecutado)
let ctxSrc = null;
try { ctxSrc = $('♻️ Build Existing Credentials').first().json; } catch(e) {}
if (!ctxSrc) { try { ctxSrc = $('✨ Build New Credentials').first().json; } catch(e) {} }
const ctx = ctxSrc || {};

const resp = $input.first().json || {};

let text = '';
try {
  text = resp?.message?.content
      || resp?.content
      || resp?.text
      || resp?.choices?.[0]?.message?.content
      || '';
  text = String(text || '').trim();
  if (!text) console.error('🔴 AI message empty. Raw:', JSON.stringify(resp).slice(0,400));
} catch (e) {
  console.error('🔴 AI parse error:', e.message);
}

if (!text) {
  text = ctx.is_existing
    ? `नमस्ते *${ctx.full_name}* जी 🙏\n\nजैसा आपने अनुरोध किया, आपके Landmark Markets अकाउंट के Login Credentials:\n\nUsername: ${ctx.username}\nPassword: ${ctx.password}\n\n🌐 Login: https://www.landmarkmarkets.in/sign-in`
    : `नमस्ते *${ctx.full_name}* जी 🙏\n\nLandmark Markets में आपका स्वागत है। आपका ट्रेडिंग अकाउंट तैयार है ✅\n\nUsername: ${ctx.username}\nPassword: ${ctx.password}\n\n🌐 Login: https://www.landmarkmarkets.in/sign-in`;
}

return [{ json: {
  whatsapp_message: text,
  full_name: ctx.full_name,
  username: ctx.username,
  password: ctx.password,
  phone: ctx.phone,
  whatsapp_number: ctx.whatsapp_number || ctx.phone,
  lead_id: ctx.lead_id,
  country: ctx.country,
  is_existing: ctx.is_existing || false,
  account_id: ctx.account_id || '',
  success: true
}}];

